export function SectionHeading({ title, tone = "dark" }: { title: string; tone?: "dark" | "light" }) {
  return (
    <div
      className={`py-[20px] text-center text-[30px] uppercase tracking-[5px] ${
        tone === "dark" ? "text-white" : "text-[#3f6ea6]"
      }`}
    >
      <h2
        className={`m-0 border-b pb-[10px] text-[30px] font-normal font-['Roboto_Condensed'] ${
          tone === "dark" ? "border-white/70" : "border-[#3f6ea6]"
        }`}
      >
        {title}
      </h2>
    </div>
  );
}

/** One dark navigation block from a section landing page. */
export function NavBlockPanel({ block }: { block: NavBlock }) {
  return (
    <div className="min-h-[275px] rounded-[2px] border border-[#4b4b4b] bg-[#222222] p-[15px]">
      <h4 className="m-0 pb-[15px] text-[16px] font-bold uppercase text-[#72b4ff]">{block.title}</h4>
      <ul className="m-0 list-none p-0">
        {block.items.map((it, i) => (
          <li key={it.label + i} className={`relative py-[10px] ${i > 0 ? "border-t border-dotted border-[#8e8c8c]" : ""}`}>
            <Link
              to={it.to}
              className="cu-panel-link relative block pr-[25px] leading-[1.2em] tracking-[0.5px] text-white no-underline"
            >
              <span>{it.label}</span>
              {it.note ? <em className="block pt-[3px] text-[12px] not-italic leading-[1em] text-gray-300">{it.note}</em> : null}
              <ChevronCircle className="absolute right-0 top-0 text-[#ffcb0b]" />
            </Link>
          </li>
        ))}
      </ul>
    </div>
  );
}

export function LandingPanel({
  intro,
  groups,
  feature,
  heading,
  tone = "dark",
}: {
  intro: string;
  groups: NavBlock[];
  feature: { src: string; alt: string; caption: string };
  heading: string;
  tone?: "dark" | "light";
}) {
  return (
    <section className="bg-[#333333] pb-[30px]">
      <div className="mx-auto max-w-[1200px] px-[10px]">
        <SectionHeading title={heading} tone={tone} />
        <p className="mx-auto max-w-[1000px] px-[10px] text-center text-[14px] leading-[1.5] text-[#cfcfcf]">{intro}</p>
        <div className="mt-[20px] flex flex-wrap gap-[10px]">
          <div className="grid w-full grid-cols-1 gap-[10px] sm:grid-cols-2 lg:w-4/5 lg:grid-cols-3">
            {groups.map((g) => (
              <NavBlockPanel key={g.title} block={g} />
            ))}
          </div>
          <aside className="w-full lg:w-[19%]">
            <img src={feature.src} alt={feature.alt} className="block w-full" />
            <p className="mt-[6px] text-[14px] italic leading-[1.4] text-[#cfcfcf]">{feature.caption}</p>
          </aside>
        </div>
      </div>
    </section>
  );
}

export function PageIntro({ lead }: { lead: string }) {
  return (
    <p className="mx-auto max-w-[1000px] px-[10px] pt-[20px] text-center text-[16px] leading-[1.6] text-[#333]">{lead}</p>
  );
}

export function FeatureBanner({ src, alt, caption }: { src: string; alt: string; caption?: string }) {
  return (
    <section className="relative">
      <img src={src} alt={alt} className="block h-[440px] w-full object-cover" />
      {caption ? (
        <div className="absolute bottom-[30px] left-[10%] max-w-[300px] bg-[rgba(0,39,76,0.78)] p-[18px] text-[15px] italic leading-[1.4] text-white">
          <span className="mb-[6px] block text-right text-[12px] not-italic">^</span>
          {caption}
        </div>
      ) : null}
    </section>
  );
}

/** Vertical strip of gallery thumbnails used by "Seize Today" style sections. */
export function GalleryStrip({
  shots,
  columns,
  showTimes = true,
}: {
  shots: { src: string; alt: string; time: string }[];
  columns: number;
  showTimes?: boolean;
}) {
  return (
    <ul
      className="m-0 grid list-none gap-[10px] p-0"
      style={{ gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))` }}
    >
      {shots.map((s, i) => (
        <li key={i} className="relative cursor-pointer">
          <img src={s.src} alt={s.alt} className="block h-[110px] w-full object-cover" />
          {showTimes ? (
            <span className="absolute bottom-0 left-0 bg-[#00274c] px-[6px] py-[2px] text-[11px] text-white">{s.time}</span>
          ) : null}
        </li>
      ))}
    </ul>
  );
}

export function SubHeading({ children }: { children: ReactNode }) {
  return (
    <h3 className="py-[24px] text-center font-['Roboto_Condensed'] text-[34px] font-light uppercase tracking-[6px] text-[#3f6ea6]">
      {children}
    </h3>
  );
}

