import { FeatureBanner, SectionHeading } from "@/components/SectionBits";
import { galleryFor } from "@/data/pages";

export interface SectionConfig {
  path: string;
  heading: string;
  intro: string;
  sideImage: string;
  sideCaption: string;
  featureImage: string;
  featureAlt: string;
  featureCaption: string;
  tone?: "dark" | "light";
  gallery?: "seize" | "student";
  galleryTitle?: string;
  galleryCopy?: string;
}

function NavBlockPanel({ title, items }: { title: string; items: { label: string; to: string; note?: string }[] }) {
  return (
    <div className="min-h-[275px] rounded-[2px] border border-[#4b4b4b] bg-[#222222] p-[15px]">
      <h4 className="m-0 pb-[15px] text-[16px] font-bold uppercase text-[#72b4ff]">{title}</h4>
      <ul className="m-0 list-none p-0">
        {items.map((it, i) => (
          <li key={it.label + i} className={`relative py-[10px] ${i > 0 ? "border-t border-dotted border-[#8e8c8c]" : ""}`}>
            <Link
              to={it.to}
              className="cu-panel-link relative block pr-[25px] leading-[1.2em] tracking-[0.5px] text-white no-underline"
            >
              <span>{it.label}</span>
              {it.note ? <em className="block pt-[3px] text-[12px] italic leading-[1em] text-gray-300">{it.note}</em> : null}
              <ChevronCircle className="absolute right-0 top-0 text-[#ffcb0b]" />
            </Link>
          </li>
        ))}
      </ul>
    </div>
  );
}

export function SectionPage({ config }: { config: SectionConfig }) {
  const groups = navGroups[config.path] ?? [];
  const gallery = config.gallery ? galleryFor(config.gallery) : null;

  return (
    <>
      <section className="bg-[#333333] pb-[30px]">
        <div className="mx-auto max-w-[1200px] px-[10px]">
          <SectionHeading title={config.heading} tone={config.tone} />
          <p className="mx-auto max-w-[1000px] px-[10px] text-center text-[14px] leading-[1.5] text-[#cfcfcf]">{config.intro}</p>
          <div className="mt-[20px] flex flex-wrap gap-[10px]">
            <div className="grid w-full grid-cols-1 gap-[10px] sm:grid-cols-2 lg:w-4/5 lg:grid-cols-3">
              {groups.map((g) => (
                <NavBlockPanel key={g.title} title={g.title} items={g.items} />
              ))}
            </div>
            <aside className="w-full lg:w-[19%]">
              <img src={config.sideImage} alt={config.featureAlt} className="block w-full" />
              <p className="mt-[6px] text-[14px] italic leading-[1.4] text-[#cfcfcf]">{config.sideCaption}</p>
            </aside>
          </div>
        </div>
      </section>

      <FeatureBanner src={config.featureImage} alt={config.featureAlt} caption={config.featureCaption} />

      {gallery ? (
        <section className="bg-white pb-[40px]">
          <div className="mx-auto max-w-[960px] px-[10px]">
            <h3 className="pb-[10px] pt-[26px] text-center font-['Roboto_Condensed'] text-[26px] font-normal uppercase tracking-[2px] text-[#4B4B4B]">
              {config.galleryTitle}
            </h3>
            <p className="mb-[20px] text-center font-['Roboto_Condensed'] text-[#757575]">{config.galleryCopy}</p>
            <GalleryStrip shots={gallery} columns={4} />
          </div>
        </section>
      ) : null}
    </>
  );
}

import type { ReactNode } from "react";
import type { GalleryShot } from "@/data/site";

export function SectionHeading({ title, tone = "dark" }: { title: string; tone?: "dark" | "light" }) {
  return (
    <div className="px-[10px] py-[20px] text-center text-[30px] uppercase tracking-[5px]">
      <h2
        className={`m-0 border-b pb-[10px] font-['Roboto_Condensed'] text-[30px] font-normal ${
          tone === "dark" ? "border-white/70 text-white" : "border-[#3f6ea6] text-[#3f6ea6]"
        }`}
      >
        {title}
      </h2>
    </div>
  );
}

export function FeatureBanner({ src, alt, caption }: { src: string; alt: string; caption?: string }) {
  return (
    <section className="relative">
      <img src={src} alt={alt} className="block h-[340px] w-full object-cover lg:h-[440px]" />
      {caption ? (
        <div className="absolute bottom-[30px] left-[10%] max-w-[300px] bg-[rgba(0,39,76,0.78)] p-[18px] text-[15px] italic leading-[1.4] text-white">
          <span className="mb-[6px] block text-right text-[12px] not-italic">^</span>
          {caption}
        </div>
      ) : null}
    </section>
  );
}

export function GalleryStrip({ shots, columns = 4 }: { shots: GalleryShot[]; columns?: number }) {
  const cls =
    columns === 4 ? "h-[152px] w-[152px]" : columns === 3 ? "h-[180px] w-[180px]" : "h-[140px] w-full";
  return (
    <ul className="m-0 list-none p-0 text-center">
      {shots.map((s, i) => (
        <li key={i} className={`group relative m-[4px_2px] inline-block overflow-hidden rounded-[2px] align-top ${cls}`}>
          <img
            src={s.src}
            alt={s.alt}
            className="absolute inset-0 m-auto h-full w-full object-cover transition-opacity duration-300 group-hover:opacity-60"
          />
          <span className="absolute bottom-0 left-0 block bg-black p-[4px] font-['Roboto_Condensed'] text-[0.8em] text-[#efefef]">
            {s.time}
          </span>
        </li>
      ))}
    </ul>
  );
}

export function Prose({ children }: { children: ReactNode }) {
  return <div className="mx-auto max-w-[900px] px-[10px] py-[20px] text-[16px] leading-[1.7] text-[#333]">{children}</div>;
}

