                  <td className="border border-[#c9c9c9] px-[12px] py-[10px] text-[16px] text-[#333]">
                    <span className="block text-[12px] uppercase text-[#777]">Department</span>
                    {r.dept}
                  </td>
                  <td className="border border-[#c9c9c9] px-[12px] py-[10px] text-[16px] text-[#333]">
                    {r.phone ? (
                      <>
                        <span className="block text-[12px] uppercase text-[#777]">Phone</span>
